 a=dict(c.execute("select * from articles where code_id=? and number=? and valid_from<=? and valid_until>? and state!='ABROGE'",('LEGITEXT000006074075',n,'2026-10-19','2026-10-19')).fetchone());a['source_id']=a.pop('id');a['source_xml']=a.pop('content_xml');key=a['code_id'],a['source_id'];a['source_notes_xml']=source_notes(c,*key)
 raw=c.execute("select xml from documents where code_id=? and id=? and kind='ARTICLE'",key).fetchone()[0];a['source_document_xml']=raw.decode();a['source_document_sha256']=hashlib.sha256(raw).hexdigest();old=c.execute('select * from drafts where code_id=? and source_id=?',key).fetchone();a['previous_draft']=dict(old) if old else None;a['previous_proposed_sha256']=hashlib.sha256((old['proposed_xml'] or '').encode()).hexdigest() if old else None;sources.append(a)
