 s=next(a for a in sources if a['number']==n);r={k:s[k] for k in ['code_id','source_id','source_sha256','number']};r.update(proposed_xml='\n'.join('<p>'+html.escape(p,quote=False)+'</p>' for p in paragraphs),reason=reason,review_notes=notes,status='rewrite_draft')
 if full:r.update(change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope=scope)
