audit={'articles':len(rows),'validate_answer':'passed','registered':False,'published':False,'source_database_read_only':True,'full_repeals':6,'normative_reductions':2,'answer_sha256':hashlib.sha256((P/'answer.json').read_bytes()).hexdigest(),'initial_to_current':[{'initial_article':'42','initial_lines':[orig['first_page_line'],orig['last_page_line']],'original_target':'L146-6-1','current_targets':names,'decision':'Supprimer le cadre facultatif dérogatoire de schéma de plage et toutes ses procédures, sans rétablir de droit pré-SRU et sans supprimer le droit littoral ou environnemental autonome. Autorisations antérieures préservées avec prescriptions, nouveaux effets dérogatoires des schémas anciens supprimés.'}],'previous_drafts':[{'number':s['number'],'sha256':s['previous_proposed_sha256']} for s in sources],'outside_corpus_required':[{'code_id':'LEGITEXT000006074220','number':'L341-16','coordination':'Retirer la référence L121-29 de la compétence de formation CDNPS, garder toutes les autres attributions.'},{'code_id':'LEGITEXT000006074220','number':'R122-17','coordination':'Retirer I50° relatif au seul schéma abrogé ; autres évaluations maintenues.'}],'semantic_caution':'Abroger une faculté de déroger au droit littoral ne réduit pas les contraintes de construction : choix explicite de suppression de toute la norme SRU, à ne pas présenter comme libéralisation.','all_sru_complete':False}
atomic('audit.json',audit);print(json.dumps(audit,ensure_ascii=False,indent=2))
